export type ExtensionStatus = "available" | "community" | "planned";

export type ExtensionType = {
  icon: string;
  name: string;
  description: string;
  status: ExtensionStatus;
  guide_url: string;
  source_url?: string;
};

/** Entry of `public/data/snippets/index.json` (generated by scripts/build-snippets.ts). */
export type SnippetType = {
  id: string;
  category: string;
  slug: string;
  /** Unique registry name, used in `/r/<name>.json`. */
  name: string;
  title: string;
  description: string;
  tags: string[];
  contributors: string[];
  languages: string[];
  verified: boolean;
  installable: boolean;
};

/** Slim snippet used by list pages (sent to the browser). */
export type ListSnippet = Pick<
  SnippetType,
  "id" | "category" | "slug" | "title" | "description" | "tags" | "languages" | "verified"
>;

/** Full snippet from `public/data/snippets/<category>/<slug>.json`. */
export type FullSnippet = SnippetType & {
  code: Record<string, string>;
  usage?: Record<string, string[]>;
  tests?: string;
  installUrl?: string;
};
